constexpr IphoneFontStrike kKeyEmphasis = {45, kKeyEmphasisGlyphs, sizeof(kKeyEmphasisGlyphs) / sizeof(kKeyEmphasisGlyphs[0]), kKeyEmphasisBitmap};
