const IphoneFontStrike &iphone_inter_font(IphoneFontSize size)
{
    switch (size) {
    case IphoneFontSize::ResultLarge: return kResultLarge;
    case IphoneFontSize::ResultMedium: return kResultMedium;
    case IphoneFontSize::ResultSmall: return kResultSmall;
    case IphoneFontSize::ResultCompact: return kResultCompact;
    case IphoneFontSize::Expression: return kExpression;
    case IphoneFontSize::KeyNumber: return kKeyNumber;
    case IphoneFontSize::KeyEmphasis: return kKeyEmphasis;
    }
    return kResultCompact;
}

const IphoneFontGlyph *iphone_inter_glyph(
    const IphoneFontStrike &strike, char code)
{
    for (size_t i = 0; i < strike.glyph_count; ++i) {
        if (strike.glyphs[i].code == code) return &strike.glyphs[i];
    }
    return nullptr;
}
